<script setup>
import { ref } from 'vue'
const apiBase=import.meta.env.VITE_API_BASE||'/api';const form=ref({username:'',password:''}),error=ref(''),loading=ref(false)
async function login(){error.value='';loading.value=true;try{const res=await fetch(`${apiBase}/auth/login`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form.value)});if(!res.ok)throw new Error('用户名或密码错误');const data=await res.json();localStorage.setItem('support_token',data.token);localStorage.setItem('support_role',data.role);localStorage.setItem('support_username',data.username);localStorage.setItem('support_profile',JSON.stringify(data));const requested=window.location.pathname+window.location.search;if(data.role==='admin'&&requested.startsWith('/admin/'))window.location.href=requested;else window.location.href=data.role==='admin'?'/admin':data.role==='processor'?'/processor':'/'}catch(e){error.value=e.message||'登录失败'}finally{loading.value=false}}
</script>
<template><main class="auth-page"><section class="auth-card"><span class="auth-badge">MYROBOOT SUPPORT</span><h1>技术支持服务平台</h1><p>客户可自助排查和提交工单；处理人员登录后进入自己的工单工作台。</p><label>用户名<input v-model="form.username" @keyup.enter="login" placeholder="请输入用户名"/></label><label>密码<input v-model="form.password" type="password" @keyup.enter="login" placeholder="请输入密码"/></label><div v-if="error" class="error">{{error}}</div><button class="login-btn" :disabled="loading" @click="login">{{loading?'登录中...':'登录'}}</button><div class="split"><span></span><em>没有账号</em><span></span></div><a class="register-link" href="/register">使用邮箱验证码注册</a></section></main></template>
<style scoped>.auth-page{min-height:100vh;display:grid;place-items:center;padding:24px;background:#f4f7fb}.auth-card{width:min(460px,100%);background:#fff;border:1px solid #e2e8f0;border-radius:22px;padding:36px;box-shadow:0 20px 60px rgba(15,35,65,.09)}.auth-badge{font-size:12px;letter-spacing:1.5px;color:#245eea}.auth-card h1{font-size:30px;margin:12px 0}.auth-card p{color:#718096;line-height:1.7;margin-bottom:24px}.auth-card label{display:grid;gap:8px;margin:14px 0;font-weight:600;color:#34455d}.auth-card input{border:1px solid #d7dfeb;border-radius:10px;padding:12px}.login-btn,.register-link{display:block;width:100%;border:0;border-radius:10px;padding:12px 16px;text-align:center;text-decoration:none}.login-btn{margin-top:20px;background:#245eea;color:#fff}.register-link{background:#eef3ff;color:#245eea}.error{color:#b42318;background:#fff1f0;border-radius:8px;padding:10px}.split{display:flex;align-items:center;gap:12px;margin:20px 0;color:#9aa7b8}.split span{height:1px;background:#e4e9f0;flex:1}.split em{font-style:normal;font-size:13px}</style>